// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new MyContract();
        // constructor sets owner = msg.sender of deployment; redeploy from owner
        vm.prank(owner);
        c = new MyContract();
    }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver.code.length == 0);
        vm.assume(uint160(receiver) > 0x10); // avoid precompiles that can revert transfer
        vm.assume(receiver != owner);
        amount = bound(amount, 0, type(uint256).max / 2);
        vm.deal(address(c), 1e20);
        amount = bound(amount, 0, address(c).balance);

        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        c.sendTo(receiver, amount);

        assertTrue(address(c).balance == balBefore - amount);
    }
}
